inline void enc_subject(std::string& out, const Subject& v, int depth) {
    out += '{';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "account");
    out += ": ";
    esc(out, v.account);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "program");
    out += ": ";
    esc(out, v.program);
    out += '\n';
    pad(out, depth);
    out += '}';
}

