inline void enc_metadata(std::string& out, const Metadata& v, int depth) {
    out += '{';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "name");
    out += ": ";
    esc(out, v.name);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "kind");
    out += ": ";
    esc(out, v.kind);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "revision");
    out += ": ";
    esc(out, v.revision);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "state");
    out += ": ";
    esc(out, v.state);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "scope");
    out += ": ";
    enc_scope(out, v.scope, depth + 1);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "registered_by");
    out += ": ";
    enc_subject(out, v.registered_by, depth + 1);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "registered");
    out += ": ";
    esc(out, write_timestamp(v.registered));
    if (!v.expires.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "expires");
        out += ": ";
        esc(out, write_timestamp(v.expires));
    }
    if (!v.header.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "header");
        out += ": ";
        esc(out, v.header);
    }
    if (!v.last_applied.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "last_applied");
        out += ": ";
        esc(out, write_timestamp(v.last_applied));
    }
    out += '\n';
    pad(out, depth);
    out += '}';
}

