inline void enc_store_result(std::string& out, const StoreResult& v, int depth) {
    if (wire_name(v.outcome).empty()) throw Refusal("bad_enum", 0);
    out += '{';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "outcome");
    out += ": ";
    esc(out, std::string(wire_name(v.outcome)));
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "revision");
    out += ": ";
    esc(out, v.revision);
    if (v.current.has_value()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "current");
        out += ": ";
        enc_metadata(out, *v.current, depth + 1);
    }
    out += '\n';
    pad(out, depth);
    out += '}';
}

